#!/usr/bin/env python3
import requests
import json
import time

# CBSA codes for the three areas
cbsas = {
    "Portland-Vancouver-Hillsboro, OR-WA": "38900",
    "Wichita, KS": "48620",
    "San Diego-Carlsbad, CA": "41740"
}

# Parameter code for Carbon Monoxide
param = "42101"

# Email and key for the test account
email = "test@aqs.api"
key = "test"

# Years to check
years = range(2000, 2011)

# Store results
results = {}

for cbsa_name, cbsa_code in cbsas.items():
    results[cbsa_name] = {}
    for year in years:
        print(f"Querying {cbsa_name} for {year}...")
        bdate = f"{year}0101"
        edate = f"{year}1231"

        url = f"https://aqs.epa.gov/data/api/dailyData/byCBSA?email={email}&key={key}&param={param}&bdate={bdate}&edate={edate}&cbsa={cbsa_code}"

        try:
            response = requests.get(url, timeout=60)
            data = response.json()

            if data["Header"][0]["status"] == "Success":
                # Filter for 8-hour CO standard (sample_duration_code "Z")
                # and check if all AQI values are <= 50 (Good)
                daily_data = data["Data"]

                # Group by date and find the maximum AQI for each day
                daily_max_aqi = {}
                for record in daily_data:
                    if record.get("sample_duration_code") == "Z" and record.get("aqi") is not None:
                        date = record["date_local"]
                        aqi = record["aqi"]
                        if date not in daily_max_aqi:
                            daily_max_aqi[date] = aqi
                        else:
                            daily_max_aqi[date] = max(daily_max_aqi[date], aqi)

                # Check if all days have AQI <= 50
                if daily_max_aqi:
                    all_good = all(aqi <= 50 for aqi in daily_max_aqi.values())
                    num_days = len(daily_max_aqi)
                    results[cbsa_name][year] = {
                        "all_good": all_good,
                        "num_days": num_days,
                        "max_aqi": max(daily_max_aqi.values()) if daily_max_aqi else None
                    }
                    print(f"  {year}: {num_days} days, all good: {all_good}, max AQI: {max(daily_max_aqi.values()) if daily_max_aqi else 'N/A'}")
                else:
                    results[cbsa_name][year] = {"all_good": False, "num_days": 0, "max_aqi": None}
                    print(f"  {year}: No 8-hour CO data")
            else:
                print(f"  Error: {data['Header'][0].get('messages', 'Unknown error')}")
                results[cbsa_name][year] = {"all_good": False, "num_days": 0, "max_aqi": None}
        except Exception as e:
            print(f"  Exception: {e}")
            results[cbsa_name][year] = {"all_good": False, "num_days": 0, "max_aqi": None}

        # Be nice to the API
        time.sleep(1)

# Find years where all three CBSAs had all Good AQI
print("\n=== Results ===")
good_years = []
for year in years:
    all_three_good = all(results[cbsa_name].get(year, {}).get("all_good", False) for cbsa_name in cbsas)
    if all_three_good:
        good_years.append(year)
        print(f"{year}: All three CBSAs had all Good AQI")

if not good_years:
    print("No years found where all three CBSAs had all Good AQI")
else:
    print(f"\nYears where all three CBSAs had all Good AQI: {', '.join(map(str, good_years))}")

